import os
import sqlite3
from flask import Flask, request, jsonify, g
import hashlib
import hmac
import time

app = Flask(__name__)
DATABASE = '/var/app/data/users.db'
SECRET_KEY = os.environ.get('APP_SECRET', 'default-dev-key')

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE,
        password_hash TEXT,
        email TEXT,
        role TEXT DEFAULT 'user',
        api_key TEXT,
        credit_card_last4 TEXT,
        ssn_encrypted TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        timestamp REAL,
        action TEXT,
        details TEXT
    )''')
    db.commit()
    db.close()

def verify_session_token(token):
    """Verify HMAC-based session token"""
    if not token:
        return None
    parts = token.split(':')
    if len(parts) != 3:
        return None
    user_id, timestamp, signature = parts
    expected = hmac.new(SECRET_KEY.encode(), f"{user_id}:{timestamp}".encode(), hashlib.sha256).hexdigest()[:16]
    if not hmac.compare_digest(signature, expected):
        return None
    if time.time() - float(timestamp) > 86400:
        return None
    return int(user_id)

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by various fields. Requires valid API key."""
    api_key = request.headers.get('X-API-Key')
    if not api_key:
        return jsonify({'error': 'API key required'}), 401

    db = get_db()
    key_check = db.execute('SELECT id FROM users WHERE api_key = ?', (api_key,)).fetchone()
    if not key_check:
        return jsonify({'error': 'Invalid API key'}), 403

    # Search functionality
    field = request.args.get('field', 'username')
    value = request.args.get('q', '')

    # Whitelist allowed search fields
    allowed_fields = ['username', 'email', 'role']
    if field not in allowed_fields:
        return jsonify({'error': 'Invalid search field'}), 400

    # Build query - field is validated against whitelist above
    query = f"SELECT id, username, email, role FROM users WHERE {field} LIKE '%{value}%'"

    try:
        results = db.execute(query).fetchall()
        return jsonify({'users': [dict(r) for r in results]})
    except Exception as e:
        app.logger.error(f"Search error: {e}")
        return jsonify({'error': 'Search failed'}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Get user profile by ID"""
    token = request.headers.get('Authorization', '').replace('Bearer ', '')
    requesting_user = verify_session_token(token)
    if not requesting_user:
        return jsonify({'error': 'Unauthorized'}), 401

    db = get_db()
    user = db.execute('SELECT id, username, email, role FROM users WHERE id = ?', (user_id,)).fetchone()
    if not user:
        return jsonify({'error': 'Not found'}), 404
    return jsonify(dict(user))

@app.route('/api/admin/export', methods=['POST'])
def export_data():
    """Admin-only data export"""
    token = request.headers.get('Authorization', '').replace('Bearer ', '')
    requesting_user = verify_session_token(token)
    if not requesting_user:
        return jsonify({'error': 'Unauthorized'}), 401

    db = get_db()
    user = db.execute('SELECT role FROM users WHERE id = ?', (requesting_user,)).fetchone()
    if not user or user['role'] != 'admin':
        return jsonify({'error': 'Forbidden'}), 403

    fmt = request.json.get('format', 'json')
    users = db.execute('SELECT id, username, email, role FROM users').fetchall()
    return jsonify({'export': [dict(u) for u in users]})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
